//! Build script for `bitwuzla`.
//!
//! The Rust enums (`Kind`, `Opt`, ...) are generated by `libbitwuzla-sys` from the
//! C headers it binds, which keeps them in sync with the linked library.
//! `libbitwuzla-sys` exports the generated file as `DEP_BITWUZLA_RUST_ENUMS`.

fn main() {
    println!("cargo:rerun-if-changed=build.rs");
    println!("cargo:rerun-if-env-changed=DEP_BITWUZLA_RUST_ENUMS");
    let enums = std::env::var("DEP_BITWUZLA_RUST_ENUMS")
        .expect("libbitwuzla-sys did not export DEP_BITWUZLA_RUST_ENUMS");
    println!("cargo:rustc-env=BITWUZLA_RUST_ENUMS={enums}");
}
